class MedicineProduct { private String medicineName,batchNo; private double price; MedicineProduct(String medicineName,String batchNo,double price){this.medicineName=medicineName;this.batchNo=batchNo;this.price=price;} public String getMedicineName(){return medicineName;} public void setMedicineName(String v){medicineName=v;} public String getBatchNo(){return batchNo;} public void setBatchNo(String v){batchNo=v;} public double getPrice(){return price;} public void setPrice(double v){price=v;} void displayProduct(){System.out.println(medicineName+" "+batchNo+" "+price);} }
public class Q06_MedicineProductMain { public static void main(String[] a){MedicineProduct p=new MedicineProduct("Tablet","B1",50);p.setPrice(55);System.out.println(p.getMedicineName());p.displayProduct();} }
